@pytest.mark.parametrize("mcp,point", [(False, "sent:search"), (True, "sent:initialize"), (True, "sent:notifications/initialized"), (True, "sent:tools/list"), (True, "sent:tools/call"), (True, "sent:model")]) def test_os_external_cli_terminated_with_unknown_send_never_automatically_repeats(tmp_path, monkeypatch, mcp, point): argv = _subprocess_inputs(tmp_path, monkeypatch, mcp=mcp) _external_kill(tmp_path, argv, point) sends = _external_sends(tmp_path) store, work_id = _expire_child_lease(tmp_path) assert store.get_item(work_id)["status"] == "leased" before = store.get_quick_scan_budget_status("quick-scan-test-policy") assert before["reserved_micros"] > 0 # Keep a valid synthetic key and HTTP stub: absence of either must not be # what prevents a second paid send. The actual durable unknown must stop it. retry = _external_spawn(tmp_path, argv, stub=True, label="unknown-reopen") assert retry.returncode != 0 assert _external_sends(tmp_path) == sends if point == "sent:model": > assert store.get_item(work_id)["status"] == "uncertain" E AssertionError: assert 'leased' == 'uncertain' E E - uncertain E + leased
